function piIsVotsalaApt(apt) {
  var g = String((apt && apt.clearGroup) || '').trim();
  if (/^votsala$/i.test(g)) return true;
  return /^votsala\b/i.test(String((apt && (apt.aptName || apt.name)) || ''));
