  var rows = list.map(function (a) {
    var bookingHotelId = piNormalizeHotelId(a && a.bookingHotelId);
    var votsala = piIsVotsalaApt(a);
    return {
      aptId: String((a && (a.id || a.aptId)) || ''),
      aptName: String((a && (a.name || a.aptName)) || ''),
      clearGroup: String((a && a.clearGroup) || '').trim(),
      bookingHotelId: bookingHotelId,
      votsala: votsala,
      folder: piBookingBillingFolder(a),
      mapped: !!bookingHotelId
    };
  });
  rows.sort(function (a, b) {
    var fc = String(a.folder || '').localeCompare(String(b.folder || ''), 'el', { numeric: true, sensitivity: 'base' });
    if (fc) return fc;
    return String(a.aptName || '').localeCompare(String(b.aptName || ''), 'el', { numeric: true, sensitivity: 'base' });
  });
  var byId = {};
  rows.forEach(function (r) {
    if (!r.bookingHotelId) return;
    if (!byId[r.bookingHotelId]) byId[r.bookingHotelId] = {};
    byId[r.bookingHotelId][r.folder] = true;
  });
  var duplicates = Object.keys(byId).filter(function (hid) { return Object.keys(byId[hid]).length > 1; }).map(function (hid) {
    return { bookingHotelId: hid, folders: Object.keys(byId[hid]).sort() };
  });
